import{_ as i,o as n,c as a,a3 as o}from"./chunks/framework.BPaanrMb.js";const h=JSON.parse('{"title":"WheelOS project and principles","description":"WheelOS product and knowledge positioning, evidence-first principles, and the boundary between commercial solutions and engineering verification.","frontmatter":{"title":"WheelOS project and principles","description":"WheelOS product and knowledge positioning, evidence-first principles, and the boundary between commercial solutions and engineering verification.","content_type":"overview","status":"repository fact","keywords":["WheelOS","Wheel.OS","Wheel.App","evidence-first","autonomous driving"]},"headers":[],"relativePath":"en/about/wheelos.md","filePath":"en/about/wheelos.md","lastUpdated":1794551845000}'),t={name:"en/about/wheelos.md"};function r(s,e,l,d,c,p){return n(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="wheelos-project-and-principles" tabindex="-1">WheelOS: project and principles <a class="header-anchor" href="#wheelos-project-and-principles" aria-label="Permalink to &quot;WheelOS: project and principles&quot;">​</a></h1><h2 id="what-is-wheelos" tabindex="-1">What is WheelOS? <a class="header-anchor" href="#what-is-wheelos" aria-label="Permalink to &quot;What is WheelOS?&quot;">​</a></h2><p>WheelOS provides integrated hardware and software solutions for low-speed autonomous vehicles, plus engineering knowledge and evidence for developers and AI agents. The public content has two product and knowledge tracks:</p><ul><li><strong>Wheel.OS</strong>: core middleware, message interfaces, sensor drivers, vehicle chassis integration, configuration, visualization, and chassis adaptation tools.</li><li><strong>Wheel.App</strong>: localization, perception, prediction, planning, control, calibration, time synchronization, vehicle dynamics, and CARLA integration.</li></ul><p>These names and capability areas come from the roadmap. Unless source code, a release artifact, or an evidence record supports a statement, it describes a target rather than a delivered capability. The purchasable integrated kit is described separately through its solution page and formal quotation.</p><h2 id="evidence-first-engineering" tabindex="-1">Evidence-first engineering <a class="header-anchor" href="#evidence-first-engineering" aria-label="Permalink to &quot;Evidence-first engineering&quot;">​</a></h2><p>WheelOS Docs is neither a pure product brochure nor a terminology-only documentation site. It is an engineering and product knowledge system designed for AI retrieval:</p><ol><li><strong>Problem first</strong>: start from observed behavior and engineering constraints.</li><li><strong>Evidence levels</strong>: separate product specifications, repository facts, design guidance, partial validation, and verified results.</li><li><strong>Reproducibility</strong>: capture versions, hardware, data, configuration, commands, metrics, and artifacts.</li><li><strong>Retain failures</strong>: failed experiments prevent AI from repeating ineffective recommendations.</li><li><strong>No boundary collapse</strong>: simulation, closed-course testing, controlled operation, and production safety cases are distinct evidence levels.</li><li><strong>Bilingual parity</strong>: Chinese and English pages preserve the same facts, numbers, status, and limitations.</li></ol><h2 id="current-known-scope" tabindex="-1">Current known scope <a class="header-anchor" href="#current-known-scope" aria-label="Permalink to &quot;Current known scope&quot;">​</a></h2><p>The repository currently contains community information, product solution material, engineering guidance, and roadmap content. Real-vehicle validation records remain limited. AI agents must keep roadmap goals separate from code, experiments, or delivered-product evidence.</p><h2 id="commercial-solution-and-evidence-boundary" tabindex="-1">Commercial solution and evidence boundary <a class="header-anchor" href="#commercial-solution-and-evidence-boundary" aria-label="Permalink to &quot;Commercial solution and evidence boundary&quot;">​</a></h2><p>The <a href="/en/solutions/integrated-autonomous-driving-kit">Integrated Autonomous Driving Kit</a> is a <code>product specification</code>. It explains configuration, delivery scope, and integration conditions. It does not replace an experiment in <code>evidence/registry.json</code>, a vehicle-level safety case, or regulatory approval. Applicability, final configuration, and price require project confirmation.</p><h2 id="related-entry-points" tabindex="-1">Related entry points <a class="header-anchor" href="#related-entry-points" aria-label="Permalink to &quot;Related entry points&quot;">​</a></h2><ul><li><a href="/en/solutions/">Autonomous driving solutions</a></li><li><a href="/en/about/system-map">System map</a></li><li><a href="/en/roadmap/2025">Roadmap</a></li><li><a href="/en/organization/organization">Organization</a></li></ul>',14)])])}const g=i(t,[["render",r]]);export{h as __pageData,g as default};
